const results = await Promise.all([
  tools.exec_command({"cmd":"gh pr view 12823 --repo jdx/mise --json number,title,state,isDraft,author,baseRefName,headRefName,headRepository,mergeable,mergeStateStatus,reviewDecision,body,url,commits,files,reviews,comments,statusCheckRollup","workdir":"/Users/jdx/src/mise","yield_time_ms":30000,"max_output_tokens":30000}),
  tools.exec_command({"cmd":"gh pr diff 12823 --repo jdx/mise","workdir":"/Users/jdx/src/mise","yield_time_ms":30000,"max_output_tokens":30000}),
  tools.exec_command({"cmd":"entire search --json --compact '12823'","workdir":"/Users/jdx/src/mise","yield_time_ms":30000,"max_output_tokens":12000}),
  tools.exec_command({"cmd":"git status --short --branch && git remote -v","workdir":"/Users/jdx/src/mise","yield_time_ms":10000,"max_output_tokens":5000})
]);
for (let i=0;i<results.length;i++) { text(`---RESULT ${i+1}---\n${results[i].output}`); }

